const insert = db.prepare(`INSERT INTO products (name,brand,category,price_bdt,compare_at_bdt,description,image_url,stock,is_demo) VALUES (?,?,?,?,NULL,?,?,0,1)`)
const update = db.prepare('UPDATE products SET brand=?, category=?, price_bdt=?, description=?, image_url=?, stock=0, is_demo=1 WHERE name=?')
const transaction = db.transaction(() => {
  let added = 0
  let refreshed = 0
  for (const p of products) {
    const keyDetails = Object.entries(p.specs).slice(0, 4).map(([key, value]) => `${key}: ${value}`).join('; ')
    const fullAbout = keyDetails ? `${p.about}\n\nKey product details: ${keyDetails}.` : p.about
    const description = `${fullAbout}\n\nSpecifications:\n${Object.entries(p.specs).map(([k,v]) => `${k}: ${v}`).join('\n')}\n\nSource: ${p.source}`
    const existing = db.prepare('SELECT id FROM products WHERE name=?').get(p.name)
    if (existing) { update.run(p.brand,p.category,p.price,description,p.image,p.name); refreshed++ }
    else { insert.run(p.name,p.brand,p.category,p.price,description,p.image); added++ }
  }
  // Remove phone listings from the storefront; preserve any item already referenced by an order.
  const removedPhones = db.prepare("DELETE FROM products WHERE category='Phones' AND id NOT IN (SELECT product_id FROM order_items)").run().changes
  const removedPowerSupplies = db.prepare("DELETE FROM products WHERE category='PC Power' AND id NOT IN (SELECT product_id FROM order_items)").run().changes
  const removedRoomItems = db.prepare("DELETE FROM products WHERE lower(trim(category)) IN ('smart home','desk setup') AND id NOT IN (SELECT product_id FROM order_items)").run().changes
  const archivedRoomItems = db.prepare("UPDATE products SET category='Archived' WHERE lower(trim(category)) IN ('smart home','desk setup') AND id IN (SELECT product_id FROM order_items)").run().changes
  return {added,refreshed,removedPhones,removedPowerSupplies,removedRoomItems,archivedRoomItems}
})

try {
  const result = transaction()
  console.log(`Catalog complete: added ${result.added}, refreshed ${result.refreshed} sample products, removed ${result.removedPhones} unreferenced phone listings, ${result.removedPowerSupplies} unreferenced PC power supplies and ${result.removedRoomItems} Smart Home/Desk Setup listings; archived ${result.archivedRoomItems} ordered room listings in ${databasePath}.`)
  console.log(`KZ IEM models included: ${products.filter((p) => p.brand === 'KZ').length}.`)
} finally { db.close() }
